mapper.select:
select id, quote_no, currency_pair, bid_rate, ask_rate, locked_rate, status, expire_time,
       remittance_no, create_time, update_time
from cross_border_fx_quote
where currency_pair = #{currencyPair}
  and status = #{status}
  and expire_time > now()
order by id asc
limit #{limit}

mapper.update:
update cross_border_fx_quote
set status = #{status}
where quote_no = #{quoteNo}
